// Mongoose schemas for FlowDesk's business data. Shapes mirror the domain
// types in `lib/types.ts` as closely as possible. Every document uses a
// plain string `id` field (not Mongo's ObjectId `_id`) so ids generated by
// the app (e.g. "proj-1", "task-14") and by `crypto.randomUUID()`-style
// generation on the server stay stable and human-readable, matching the
// original in-memory seed data.
//
// Auth/session data (User, registered accounts, session tokens) is NOT
// modeled here — that stays mocked client-side in lib/store.ts.
import { Schema, model, models, type Model, type SchemaOptions } from "mongoose";
import type {
  Organization,
  TeamMember,
  Project,
  Task,
  Customer,
  AppNotification,
  Invoice,
  ApiKey,
  Webhook,
  LoginHistoryEntry,
  ActiveSession,
  IntegrationState,
  NotificationPrefs,
} from "../types";

// Singleton documents (Organization, IntegrationState, NotificationPrefs) all
// use this fixed id, since FlowDesk is a single-tenant demo app with exactly
// one organization.
export const SINGLETON_ID = "singleton";

// `SchemaOptions` is intentionally left generic (untyped `any`) here: pinning
// it to each domain type below runs into a known Mongoose typings issue
// where a `toJSON.transform` typed against a specific document shape makes
// the resulting `Schema<T>` incompatible with itself (see mongoose/mongoose
// issues around `SchemaOptions<DocType>` + custom `transform`). The runtime
// behavior (strip `_id`, drop `__v`) is simple and covered by the shared
// stripMongoId helper + integration tests, so the loosened type here is a
// deliberate, narrow trade-off rather than a general `any` escape hatch.
function baseOptions(): SchemaOptions {
  return {
    versionKey: false,
    toJSON: {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      transform: (_doc: any, ret: Record<string, unknown>) => {
        delete ret._id;
        return ret;
      },
    },
  };
}

const OrganizationSchema = new Schema<Organization>(
  {
    id: { type: String, required: true, unique: true },
    name: { type: String, required: true },
    plan: { type: String, required: true, enum: ["Free", "Starter", "Pro", "Enterprise"] },
    billingCycle: { type: String, required: true, enum: ["Monthly", "Annual"] },
  },
  baseOptions()
);

const TeamMemberSchema = new Schema<TeamMember>(
  {
    id: { type: String, required: true, unique: true },
    name: { type: String, required: true },
    email: { type: String, required: true, index: true },
    role: { type: String, required: true, enum: ["Owner", "Admin", "Member", "Viewer"] },
    avatarUrl: { type: String, required: true },
    status: { type: String, required: true, enum: ["Active", "Invited"] },
    joinedAt: { type: String, required: true },
  },
  baseOptions()
);

const ProjectSchema = new Schema<Project>(
  {
    id: { type: String, required: true, unique: true },
    name: { type: String, required: true },
    description: { type: String, default: "" },
    status: { type: String, required: true, enum: ["Planning", "Active", "Completed", "Archived"] },
    ownerId: { type: String, required: true },
    progress: { type: Number, required: true, min: 0, max: 100 },
    dueDate: { type: String, required: true },
    createdAt: { type: String, required: true },
  },
  baseOptions()
);

const TaskSchema = new Schema<Task>(
  {
    id: { type: String, required: true, unique: true },
    projectId: { type: String, required: true, index: true },
    title: { type: String, required: true },
    description: { type: String, default: "" },
    status: { type: String, required: true, enum: ["Todo", "In Progress", "Review", "Completed"] },
    priority: { type: String, required: true, enum: ["Low", "Medium", "High", "Urgent"] },
    assigneeId: { type: String, default: null },
    dueDate: { type: String, required: true },
    createdAt: { type: String, required: true },
  },
  baseOptions()
);

const CustomerSchema = new Schema<Customer>(
  {
    id: { type: String, required: true, unique: true },
    name: { type: String, required: true },
    company: { type: String, default: "" },
    email: { type: String, required: true },
    status: { type: String, required: true, enum: ["Lead", "Active", "Churned"] },
    createdAt: { type: String, required: true },
  },
  baseOptions()
);

const AppNotificationSchema = new Schema<AppNotification>(
  {
    id: { type: String, required: true, unique: true },
    type: { type: String, required: true, enum: ["task", "project", "team", "billing", "system"] },
    title: { type: String, required: true },
    message: { type: String, required: true },
    read: { type: Boolean, required: true, default: false },
    createdAt: { type: String, required: true },
  },
  baseOptions()
);

const InvoiceSchema = new Schema<Invoice>(
  {
    id: { type: String, required: true, unique: true },
    number: { type: String, required: true },
    date: { type: String, required: true },
    amount: { type: Number, required: true },
    status: { type: String, required: true, enum: ["Paid", "Due"] },
  },
  baseOptions()
);

const ApiKeySchema = new Schema<ApiKey>(
  {
    id: { type: String, required: true, unique: true },
    name: { type: String, required: true },
    maskedKey: { type: String, required: true },
    createdAt: { type: String, required: true },
    lastUsedAt: { type: String, default: null },
  },
  baseOptions()
);

const WebhookSchema = new Schema<Webhook>(
  {
    id: { type: String, required: true, unique: true },
    url: { type: String, required: true },
    events: { type: [String], default: [] },
    active: { type: Boolean, required: true, default: true },
    createdAt: { type: String, required: true },
  },
  baseOptions()
);

const LoginHistoryEntrySchema = new Schema<LoginHistoryEntry>(
  {
    id: { type: String, required: true, unique: true },
    device: { type: String, required: true },
    location: { type: String, required: true },
    ip: { type: String, required: true },
    at: { type: String, required: true },
    success: { type: Boolean, required: true },
  },
  baseOptions()
);

const ActiveSessionSchema = new Schema<ActiveSession>(
  {
    id: { type: String, required: true, unique: true },
    device: { type: String, required: true },
    location: { type: String, required: true },
    lastActive: { type: String, required: true },
    current: { type: Boolean, required: true, default: false },
  },
  baseOptions()
);

const IntegrationStateSchema = new Schema<IntegrationState & { id: string }>(
  {
    id: { type: String, required: true, unique: true, default: SINGLETON_ID },
    slack: { type: Boolean, required: true, default: false },
    googleCalendar: { type: Boolean, required: true, default: false },
  },
  baseOptions()
);

const NotificationPrefsSchema = new Schema<NotificationPrefs & { id: string }>(
  {
    id: { type: String, required: true, unique: true, default: SINGLETON_ID },
    email: { type: Boolean, required: true, default: true },
    push: { type: Boolean, required: true, default: true },
    taskUpdates: { type: Boolean, required: true, default: true },
    weeklyReport: { type: Boolean, required: true, default: false },
  },
  baseOptions()
);

// `models.X ?? model(...)` avoids Mongoose's "Cannot overwrite model once
// compiled" error under Next.js dev hot-reload, where this module can be
// re-evaluated without the process (and mongoose's model registry)
// restarting.
function getModel<T>(name: string, schema: Schema<T>): Model<T> {
  return (models[name] as Model<T>) ?? model<T>(name, schema);
}

export const OrganizationModel = getModel<Organization>("Organization", OrganizationSchema);
export const TeamMemberModel = getModel<TeamMember>("TeamMember", TeamMemberSchema);
export const ProjectModel = getModel<Project>("Project", ProjectSchema);
export const TaskModel = getModel<Task>("Task", TaskSchema);
export const CustomerModel = getModel<Customer>("Customer", CustomerSchema);
export const AppNotificationModel = getModel<AppNotification>("AppNotification", AppNotificationSchema);
export const InvoiceModel = getModel<Invoice>("Invoice", InvoiceSchema);
export const ApiKeyModel = getModel<ApiKey>("ApiKey", ApiKeySchema);
export const WebhookModel = getModel<Webhook>("Webhook", WebhookSchema);
export const LoginHistoryEntryModel = getModel<LoginHistoryEntry>("LoginHistoryEntry", LoginHistoryEntrySchema);
export const ActiveSessionModel = getModel<ActiveSession>("ActiveSession", ActiveSessionSchema);
export const IntegrationStateModel = getModel<IntegrationState & { id: string }>("IntegrationState", IntegrationStateSchema);
export const NotificationPrefsModel = getModel<NotificationPrefs & { id: string }>("NotificationPrefs", NotificationPrefsSchema);
